-- LOCAL-ONLY seed for tests/rls_hardening_test_plan.sql (run as superuser on
-- a throwaway DB after local_stub_schema.sql and BEFORE the migration, so the
-- join-code copy step is exercised). Fake people, fake companies.
-- auth uid = 00000000-...-00000000XXXX, users.id = 10000000-...-00000000XXXX

SELECT ('10000000-0000-0000-0000-0000000000' || right(id::text, 2))::uuid, id::text, email, split_part(email, '@', 1), 'Test', now()
FROM auth.users WHERE right(id::text, 2) NOT IN ('c2');  -- 'fresh' has no users row yet





